const PLAN_KEY='learning-garden-planning-v1';let planning=null,planningStorageOK=true,boardMonth='',boardSprint='';
try{const v=localStorage.getItem(PLAN_KEY);if(v)planning=JSON.parse(v)}catch{planningStorageOK=false}
function monthLabel(month){return new Date(month+'-15T12:00:00').toLocaleDateString('en-IN',{month:'long',year:'numeric'})}
function defaultPlanning(){return {months:['2026-11','2026-12','2027-01'],sprints:[{id:'devfest-week-1',month:'2026-11',name:'Week 1 · Python foundations',start:'2026-11-02',end:'2026-11-08',goal:'Kaggle Intro to Programming, then Python. Practise one small CSV script.'},{id:'devfest-week-2',month:'2026-11',name:'Week 2 · GitHub & APIs',start:'2026-11-09',end:'2026-11-15',goal:'Create a repository. Read JSON and call an API from Python.'},{id:'devfest-week-3',month:'2026-11',name:'Week 3 · Gemini',start:'2026-11-16',end:'2026-11-22',goal:'Use AI Studio and build a small Gemini assistant.'},{id:'devfest-week-4',month:'2026-11',name:'Week 4 · Agents & mini-project',start:'2026-11-23',end:'2026-11-29',goal:'Explore agent material and rehearse one working project.'},{id:'devfest-final-polish',month:'2026-12',name:'DevFest · Final preparation',start:'2026-12-01',end:'2026-12-04',goal:'Review workshop prerequisites, fix outstanding issues and practise your demo.'}],initialized:false}}
function persistPlanning(){try{planning.view={month:boardMonth,sprint:boardSprint};localStorage.setItem(PLAN_KEY,JSON.stringify(planning));planningStorageOK=true}catch{planningStorageOK=false}}
function preparePlanning(){if(!planning||!Array.isArray(planning.months)||!Array.isArray(planning.sprints))planning=defaultPlanning();if(!planning.initialized){for(const t of boardTasks||[]){if(t.sprintId!==undefined)continue;t.sprintId='';if(t.resourceId!=='devfest'||t.status==='Backlog / Later')continue;let match;if(t.dueDate||t.startDate){const date=t.dueDate||t.startDate;match=planning.sprints.find(s=>s.start<=date&&date<=s.end)}else{const week=(t.sourceStep||'').match(/^Week ([1-4])/);if(week)match=planning.sprints.find(s=>s.id==='devfest-week-'+week[1])}if(match)t.sprintId=match.id;}planning.initialized=true;persistTasks();persistPlanning()}if(!boardMonth){boardMonth=planning.view?.month||'2026-11';boardSprint=planning.view?.sprint||''}if(!['all','unscheduled',...planning.months].includes(boardMonth))boardMonth=planning.months[0]||'unscheduled';if(!boardSprint)chooseFirstSprint();if(boardSprint!=='all'&&!planning.sprints.some(s=>s.id===boardSprint&&s.month===boardMonth))boardSprint='all';reconcileDatedTasks()}
function chooseFirstSprint(){const list=planning.sprints.filter(s=>s.month===boardMonth).sort((a,b)=>a.start.localeCompare(b.start));boardSprint=list.find(s=>s.start<=localDay()&&localDay()<=s.end)?.id||list[0]?.id||'all'}
function getSprint(t){return planning?.sprints?.find(s=>s.id===t.sprintId)}
function effectiveTaskDue(t){return t.dueDate||getSprint(t)?.end||''}
function matchesPlanning(t){if(boardMonth==='all')return true;const sprint=getSprint(t);if(boardMonth==='unscheduled')return !sprint;return !!sprint&&sprint.month===boardMonth&&(boardSprint==='all'||sprint.id===boardSprint)}
function sprintOptions(value){return '<option value="">Unscheduled / Later</option>'+planning.sprints.slice().sort((a,b)=>a.start.localeCompare(b.start)).map(s=>`<option value="${esc(s.id)}" ${s.id===value?'selected':''}>${esc(monthLabel(s.month))} · ${esc(s.name)}</option>`).join('')}
function renderPlanning(){const selected=planning.sprints.find(s=>s.id===boardSprint);const sprints=planning.sprints.filter(s=>s.month===boardMonth).sort((a,b)=>a.start.localeCompare(b.start));return `<section class="planning-panel" aria-label="Month and sprint planning"><div class="planning-top"><div><div class="eyebrow">PLAN A LITTLE. FINISH A LITTLE.</div><h2>One sprint at a time.</h2></div><button id="addPlanMonth">＋ Add month</button></div><div class="month-tabs">${planning.months.slice().sort().map(m=>`<button data-plan-month="${m}" class="${boardMonth===m?'chosen':''}">${monthLabel(m)}</button>`).join('')}<button data-plan-month="unscheduled" class="${boardMonth==='unscheduled'?'chosen':''}">Unscheduled / Later <span>${boardTasks.filter(t=>!t.archived&&!getSprint(t)).length}</span></button><button data-plan-month="all" class="${boardMonth==='all'?'chosen':''}">All months</button></div><div class="sprint-toolbar"><div style="flex:1;min-width:190px"><label for="sprintSelect">Sprint</label><select id="sprintSelect" ${['all','unscheduled'].includes(boardMonth)?'disabled':''}>${['all','unscheduled'].includes(boardMonth)?`<option>${boardMonth==='all'?'All sprints':'Unscheduled tasks'}</option>`:`<option value="all" ${boardSprint==='all'?'selected':''}>All sprints in ${esc(monthLabel(boardMonth))}</option>${sprints.map(s=>`<option value="${esc(s.id)}" ${boardSprint===s.id?'selected':''}>${esc(s.name)} · ${taskDate(s.start)}–${taskDate(s.end)}</option>`).join('')}`}</select></div><button id="newSprint">＋ New sprint</button>${selected?'<button id="editSprint">Edit sprint</button>':''}</div>${selected?`<div class="sprint-goal"><strong>${esc(selected.name)}</strong><span>${taskDate(selected.start)} → ${taskDate(selected.end)}</span><p>${esc(selected.goal||'Set one achievable outcome for this sprint.')}</p></div>`:sprints.length===0&&!['all','unscheduled'].includes(boardMonth)?'<p class="muted" style="font-size:13px;margin:14px 0 0">A fresh month. Create a sprint, then add or move tasks into it.</p>':''}<p class="planning-help">Task dates automatically choose the matching month and sprint: deadline first, then start date. You can switch a task to manual placement. Suggested sprint dates remain editable. Unscheduled keeps future ideas out of your current board.</p></section>`}
function openSprint(id){preparePlanning();const s=planning.sprints.find(s=>s.id===id)||{month:/^\d{4}-\d{2}$/.test(boardMonth)?boardMonth:planning.months[0],name:'',start:'',end:'',goal:''};$('sprintId').value=s.id||'';for(const [key,field] of [['name','sprintName'],['month','sprintMonth'],['start','sprintStart'],['end','sprintEnd'],['goal','sprintGoal']])$(field).value=s[key]||'';$('sprintError').textContent='';$('sprintDialogTitle').textContent=s.id?'Shape your sprint':'Create a focused sprint';$('sprintDialog').showModal()}
function validateImportedPlanning(value){if(!value||!Array.isArray(value.months)||!Array.isArray(value.sprints)||value.sprints.length>2000)throw Error('Invalid sprint plan');const months=[...new Set(value.months)];if(!months.every(m=>/^\d{4}-(0[1-9]|1[0-2])$/.test(m)))throw Error('Invalid month');const ids=new Set();const sprints=value.sprints.map(s=>{if(!s||typeof s.id!=='string'||ids.has(s.id)||typeof s.name!=='string'||!months.includes(s.month)||!/^\d{4}-\d{2}-\d{2}$/.test(s.start)||!/^\d{4}-\d{2}-\d{2}$/.test(s.end)||s.start>s.end||s.start.slice(0,7)!==s.month)throw Error('Invalid sprint');ids.add(s.id);return {id:s.id,name:s.name,month:s.month,start:s.start,end:s.end,goal:typeof s.goal==='string'?s.goal:''}});return {months,sprints,initialized:true}}
function mergeImportedPlanning(incoming){if(!incoming)return;preparePlanning();planning.months=[...new Set([...planning.months,...incoming.months])];const map=new Map(planning.sprints.map(s=>[s.id,s]));incoming.sprints.forEach(s=>map.set(s.id,s));planning.sprints=[...map.values()];persistPlanning()}
function setupPlanner(){document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.planMonth){boardMonth=b.dataset.planMonth;chooseFirstSprint();boardFilter='All';persistPlanning();render()}if(b.id==='newSprint')openSprint();if(b.id==='editSprint')openSprint(boardSprint);if(b.id==='closeSprint'||b.id==='cancelSprint')$('sprintDialog').close();if(b.id==='addPlanMonth'){$('monthToAdd').value=/^\d{4}-\d{2}$/.test(boardMonth)?boardMonth:localDay().slice(0,7);$('monthDialog').showModal()}if(b.id==='cancelPlanMonth')$('monthDialog').close()});document.addEventListener('change',e=>{if(['taskStart','taskDue','taskAutoSchedule'].includes(e.target.id))previewTaskDateRoute();if(e.target.id==='taskSprint')e.target.dataset.manualValue=e.target.value;if(e.target.id==='sprintSelect'){boardSprint=e.target.value;boardFilter='All';persistPlanning();render()}if(e.target.dataset.taskSprint){const t=boardTasks.find(t=>t.id===e.target.dataset.taskSprint);t.sprintId=e.target.value;persistTasks();render();toast('Task moved to '+(getSprint(t)?.name||'Unscheduled / Later'))}});$('monthForm').addEventListener('submit',e=>{e.preventDefault();const m=$('monthToAdd').value;if(!planning.months.includes(m))planning.months.push(m);boardMonth=m;chooseFirstSprint();persistPlanning();$('monthDialog').close();render()});$('sprintForm').addEventListener('submit',e=>{e.preventDefault();const name=$('sprintName').value.trim(),month=$('sprintMonth').value,start=$('sprintStart').value,end=$('sprintEnd').value;if(!name||!start||!end||start>end||start.slice(0,7)!==month){$('sprintError').textContent='Enter a name, start within the selected month, and end on or after the start date.';return}const s={id:$('sprintId').value||newId(),name,month,start,end,goal:$('sprintGoal').value.trim()};const i=planning.sprints.findIndex(x=>x.id===s.id);if(i>=0)planning.sprints[i]=s;else planning.sprints.push(s);if(!planning.months.includes(month))planning.months.push(month);boardMonth=month;boardSprint=s.id;persistPlanning();$('sprintDialog').close();render();toast('Sprint saved')})}
function isValidScheduleDate(date){return typeof date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(date)&&!Number.isNaN(Date.parse(date+'T00:00:00Z'))&&new Date(date+'T00:00:00Z').toISOString().slice(0,10)===date}function taskScheduleDate(t){return t.dueDate||t.startDate||''}
function dateSprintMatch(date,currentId=''){const month=date.slice(0,7),list=planning.sprints.filter(s=>s.month===month&&s.start<=date&&date<=s.end);return list.find(s=>s.id===currentId)||list.sort((a,b)=>(Date.parse(a.end)-Date.parse(a.start))-(Date.parse(b.end)-Date.parse(b.start))||b.start.localeCompare(a.start)||a.id.localeCompare(b.id))[0]}
function automaticSprintForDate(date){let sprint=dateSprintMatch(date);if(sprint)return sprint;const [year,month,day]=date.split('-').map(Number),dayOfWeek=new Date(Date.UTC(year,month-1,day)).getUTCDay(),monday=day-((dayOfWeek+6)%7),lastDay=new Date(Date.UTC(year,month,0)).getUTCDate(),startDay=Math.max(1,monday),endDay=Math.min(lastDay,monday+6),prefix=date.slice(0,7),start=prefix+'-'+String(startDay).padStart(2,'0'),end=prefix+'-'+String(endDay).padStart(2,'0');const shortMonth=new Date(date+'T12:00:00').toLocaleDateString('en-IN',{month:'short'});sprint={id:newId(),month:prefix,name:`${startDay}–${endDay} ${shortMonth} · Weekly sprint`,start,end,goal:'A focused week for the tasks you have dated here.'};if(!planning.months.includes(prefix))planning.months.push(prefix);planning.sprints.push(sprint);return sprint}
function assignTaskByDates(t){const date=taskScheduleDate(t);if(t.autoSchedule===false||!isValidScheduleDate(date))return null;const sprint=dateSprintMatch(date,t.sprintId)||automaticSprintForDate(date);if(!planning.months.includes(sprint.month))planning.months.push(sprint.month);const changed=t.sprintId!==sprint.id;t.sprintId=sprint.id;return {sprint,changed}}
function reconcileDatedTasks(){let first=null,changed=false;for(const t of boardTasks||[]){const result=assignTaskByDates(t);if(result?.changed){changed=true;if(!first&&!t.archived)first=result.sprint}}const initial=!planning.dateRoutingInitialized;planning.dateRoutingInitialized=true;if(initial&&first){boardMonth=first.month;boardSprint=first.id}if(changed)persistTasks();if(changed||initial)persistPlanning()}
function followDatedTask(t){const result=assignTaskByDates(t);if(!result)return null;boardMonth=result.sprint.month;boardSprint=result.sprint.id;boardFilter='All';boardResource='all';query='';$('search').value='';persistPlanning();return result.sprint}
function previewTaskDateRoute(){const auto=$('taskAutoSchedule').checked,date=$('taskDue').value||$('taskStart').value,select=$('taskSprint'),manual=select.dataset.manualValue||'';select.innerHTML=sprintOptions(manual);select.disabled=auto&&!!date;if(auto&&date){const match=dateSprintMatch(date,manual);if(match)select.value=match.id;else{const option=document.createElement('option');option.value='__automatic__';option.textContent=monthLabel(date.slice(0,7))+' · Weekly sprint from task date';select.append(option);select.value=option.value}$('taskScheduleHelp').textContent=( $('taskDue').value?'Deadline':'Start date')+' '+taskDate(date)+' → '+monthLabel(date.slice(0,7))+(match?' · '+match.name:'. A matching weekly sprint will be created when you save.')}else{$('taskScheduleHelp').textContent=auto?'No dates yet—choose a sprint for now. Adding a deadline or start date will place it automatically.':'Manual placement is on. Your chosen sprint will stay as selected.'}}
